<?php
declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();$role=(string)($_SESSION['role']??'');if(!in_array($role,['hr','director','sub_director','headteacher'],true)){http_response_code(403);exit('Your role cannot access staff documents.');}$uid=(int)$_SESSION['user_id'];$school=filter_var($_GET['school_id']??null,FILTER_VALIDATE_INT);$staffId=filter_var($_GET['user_id']??null,FILTER_VALIDATE_INT);if(!$school||!$staffId){http_response_code(422);exit('Choose a school and staff member.');}$q=db()->prepare('SELECT s.name school_name,u.name staff_name,u.role FROM schools s JOIN school_memberships m ON m.school_id=s.id AND m.user_id=? JOIN school_memberships sm ON sm.school_id=s.id JOIN users u ON u.id=sm.user_id WHERE s.id=? AND u.id=?');$q->execute([$uid,$school,$staffId]);$staff=$q->fetch();$allowedStaffRoles=['admin','director','sub_director','headteacher','head_academic','department_head','assistant_academic','examination_officer','teacher','driver','hr','storekeeper','bursar'];if(!$staff||!in_array((string)$staff['role'],$allowedStaffRoles,true)){http_response_code(404);exit('Staff account not found in this school.');}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Staff documents · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script><script defer src="assets/staff-documents.js"></script></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">People <span>/</span> Staff documents</div></header><div class="page-content" data-staff-documents data-api="api/employee_documents.php" data-school="<?=$school?>" data-user="<?=$staffId?>" data-role="<?=e($role)?>" data-csrf="<?=e(csrf_token())?>"><section class="welcome-row"><div><div class="eyebrow"><?=e($staff['school_name'])?></div><h1><?=e($staff['staff_name'])?></h1><p class="muted"><?=e(str_replace('_',' ',$staff['role']))?> · Staff documents</p></div><a class="button" href="staff_profiles.php?school_id=<?=$school?>">Back to staff profiles</a></section><div data-documents-status class="notice" role="status" aria-live="polite" hidden></div><?php if($role==='hr'):?><section class="note-create"><div class="section-heading"><h2>Upload a staff document</h2></div><form data-document-form class="note-form" enctype="multipart/form-data"><div class="form-grid"><div><label for="document-category">Category</label><select id="document-category" name="category"><option value="contract">Contract</option><option value="qualification">Qualification</option><option value="identity">Identity document</option><option value="other">Other</option></select></div><div><label for="staff-document-file">File</label><input id="staff-document-file" type="file" name="document" accept="application/pdf,image/jpeg,image/png" required><small>PDF, JPEG or PNG; up to 10 MB.</small></div></div><button class="button primary" type="submit">Upload document</button></form></section><?php endif;?><section class="content-section"><div class="section-heading"><h2>Documents</h2><button class="button" type="button" data-documents-refresh>Refresh</button></div><div class="question-list" data-documents-list><p class="muted">Loading documents…</p></div></section><footer class="page-footer">ShuleLite · Staff documents</footer></div></main></div></div></body></html>
